const MYDTU_TIMETABLE_URL =
  "https://mydtu.duytan.edu.vn/sites/index.aspx?p=home_timetable&functionid=13";

const ADAPTER_KEY = "mydtu_timetable_v1";
const ADAPTER_VERSION = "1.0.0";

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function normalizeSpace(s) {
  return String(s || "").replace(/\s+/g, " ").trim();
}

function hasTimetableMarkers(html) {
  const text = String(html || "");
  return (
    text.includes("Lịch học") ||
    text.includes("L&#7883;ch h&#7885;c") ||
    text.includes("rsContentTable") ||
    text.includes("rsApt") ||
    text.includes("RadScheduler")
  );
}

async function checkSession() {
  try {
    const res = await fetch(MYDTU_TIMETABLE_URL, {
      method: "GET",
      credentials: "include",
      cache: "no-store"
    });

    const html = await res.text();
    const ok = res.ok && hasTimetableMarkers(html);

    return {
      connected: ok,
      status: res.status
    };
  } catch (e) {
    return {
      connected: false,
      status: 0,
      error: String(e?.message || e)
    };
  }
}

async function openOrFocusMydtuLogin() {
  const tabs = await chrome.tabs.query({
    url: ["https://mydtu.duytan.edu.vn/*"]
  });

  const exact = tabs.find((t) => String(t.url || "").includes("p=home_timetable"));

  if (exact?.id) {
    await chrome.tabs.update(exact.id, {
      active: true,
      url: MYDTU_TIMETABLE_URL
    });
    if (exact.windowId) {
      await chrome.windows.update(exact.windowId, { focused: true });
    }
    return { tabId: exact.id, reused: true };
  }

  if (tabs[0]?.id) {
    await chrome.tabs.update(tabs[0].id, {
      active: true,
      url: MYDTU_TIMETABLE_URL
    });
    if (tabs[0].windowId) {
      await chrome.windows.update(tabs[0].windowId, { focused: true });
    }
    return { tabId: tabs[0].id, reused: true };
  }

  const created = await chrome.tabs.create({
    url: MYDTU_TIMETABLE_URL,
    active: true
  });

  return { tabId: created.id, reused: false };
}

async function ensureTimetableTab() {
  const tabs = await chrome.tabs.query({
    url: ["https://mydtu.duytan.edu.vn/*"]
  });

  const exact = tabs.find((t) => String(t.url || "").includes("p=home_timetable"));
  if (exact?.id) {
    if (exact.url !== MYDTU_TIMETABLE_URL) {
      await chrome.tabs.update(exact.id, { url: MYDTU_TIMETABLE_URL, active: false });
    }
    return exact.id;
  }

  if (tabs[0]?.id) {
    await chrome.tabs.update(tabs[0].id, {
      url: MYDTU_TIMETABLE_URL,
      active: false
    });
    return tabs[0].id;
  }

  const created = await chrome.tabs.create({
    url: MYDTU_TIMETABLE_URL,
    active: false
  });

  if (!created.id) {
    throw new Error("Không tạo được tab MYDTU.");
  }

  return created.id;
}

function waitForTabComplete(tabId, timeoutMs = 20000) {
  return new Promise((resolve, reject) => {
    const startedAt = Date.now();

    const timer = setInterval(async () => {
      try {
        const tab = await chrome.tabs.get(tabId);

        if (tab.status === "complete") {
          clearInterval(timer);
          resolve(true);
          return;
        }

        if (Date.now() - startedAt > timeoutMs) {
          clearInterval(timer);
          reject(new Error("Tab load timeout"));
        }
      } catch (e) {
        clearInterval(timer);
        reject(e);
      }
    }, 400);
  });
}

async function scrapeTimetableInTab(tabId) {
  const results = await chrome.scripting.executeScript({
    target: { tabId },
    world: "MAIN",
    func: () => {
      function normalizeSpace(s) {
        return String(s || "").replace(/\s+/g, " ").trim();
      }

      function textOf(selector) {
        const el = document.querySelector(selector);
        return normalizeSpace(el?.textContent || "");
      }

      function getWeekLabel() {
        return (
          textOf("#tuanthu") ||
          textOf(".rsHeader h2") ||
          textOf(".functionname") ||
          textOf(".title") ||
          "MYDTU_TIMETABLE"
        );
      }

      function parseTitle(rawTitle) {
        const raw = normalizeSpace(rawTitle);
        const parts = raw.split("|").map((x) => normalizeSpace(x));

        const courseCode = parts[0] || "";
        const courseName = parts[1] || "";
        const location = parts[2] || "";
        const timeRange = parts[3] || "";

        const [startTime = "", endTime = ""] = timeRange.split("-").map((x) => normalizeSpace(x));

        let room = location;
        let campus = null;

        const commaIdx = location.indexOf(",");
        if (commaIdx >= 0) {
          room = normalizeSpace(location.slice(0, commaIdx));
          campus = normalizeSpace(location.slice(commaIdx + 1)) || null;
        }

        return {
          courseCode,
          courseName,
          room,
          campus,
          startTime,
          endTime
        };
      }

      function getDayOfWeekFromAppointment(aptEl) {
        const td = aptEl.closest("td");
        if (!td || !td.parentElement) return null;

        const row = td.parentElement;
        const cells = Array.from(row.children).filter((el) => el.tagName === "TD");
        const idx = cells.indexOf(td);
        if (idx < 0) return null;

        return idx + 1; // 1..7 => Thứ 2..CN
      }

      const aptEls = Array.from(document.querySelectorAll(".rsApt[title], div[title*='|']"))
        .filter((el) => {
          const title = normalizeSpace(el.getAttribute("title") || "");
          return !!title && /\d{2}:\d{2}\s*-\s*\d{2}:\d{2}/.test(title);
        });

      if (!aptEls.length) {
        return {
          ok: false,
          error:
            "Không tìm thấy block lịch trên trang MYDTU. Hãy mở đúng trang Lịch học tuần rồi thử lại.",
          debug: {
            href: location.href,
            title: document.title,
            weekLabel: getWeekLabel()
          }
        };
      }

      const weekLabel = getWeekLabel();
      const semester = weekLabel || "MYDTU_TIMETABLE";
      const sourcePage = location.href;

      const items = [];
      const seen = new Set();

      for (const el of aptEls) {
        const title = normalizeSpace(el.getAttribute("title") || "");
        const parsed = parseTitle(title);
        const dayOfWeek = getDayOfWeekFromAppointment(el);

        if (!parsed.courseCode || !parsed.startTime || !parsed.endTime || !dayOfWeek) {
          continue;
        }

        const key = [
          semester,
          parsed.courseCode,
          parsed.courseName,
          dayOfWeek,
          parsed.startTime,
          parsed.endTime,
          parsed.room,
          parsed.campus || ""
        ].join("|");

        if (seen.has(key)) continue;
        seen.add(key);

        items.push({
          semester,
          courseCode: parsed.courseCode,
          courseName: parsed.courseName || null,
          dayOfWeek,
          startTime: parsed.startTime,
          endTime: parsed.endTime,
          room: parsed.room || "",
          campus: parsed.campus || null,
          weeksIncluded: weekLabel || null,
          weeksCanceled: null,
          rawTitle: title
        });
      }

      if (!items.length) {
        return {
          ok: false,
          error: "Đã đọc được DOM nhưng parse ra 0 môn học."
        };
      }

      return {
        ok: true,
        payload: {
          adapterKey: "mydtu_timetable_v1",
          adapterVersion: "1.0.0",
          semester,
          sourcePage,
          items
        }
      };
    }
  });

  return results?.[0]?.result || { ok: false, error: "Không lấy được kết quả scrape." };
}

async function syncTimetableFromTab() {
  const session = await checkSession();
  if (!session.connected) {
    return {
      ok: false,
      error: "Bạn chưa đăng nhập MYDTU hoặc phiên đăng nhập đã hết hạn."
    };
  }

  const tabId = await ensureTimetableTab();
  await waitForTabComplete(tabId, 20000);

  // Cho MYDTU thêm thời gian render scheduler
  await sleep(2500);

  // thử scrape lần 1
  let result = await scrapeTimetableInTab(tabId);
  if (result?.ok) {
    return {
      ok: true,
      data: result.payload
    };
  }

  // thử reload đúng URL rồi scrape lần 2
  await chrome.tabs.update(tabId, { url: MYDTU_TIMETABLE_URL, active: false });
  await waitForTabComplete(tabId, 20000);
  await sleep(3500);

  result = await scrapeTimetableInTab(tabId);
  if (result?.ok) {
    return {
      ok: true,
      data: result.payload
    };
  }

  return {
    ok: false,
    error: result?.error || "Scrape timetable failed"
  };
}

chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  (async () => {
    try {
      if (!msg || msg.type !== "WEB_TO_EXTENSION") {
        sendResponse({ ok: false, error: "Unknown message" });
        return;
      }

      if (msg.action === "MYDTU_OPEN_LOGIN") {
        const r = await openOrFocusMydtuLogin();
        sendResponse({ ok: true, data: r });
        return;
      }

      if (msg.action === "MYDTU_CHECK_SESSION") {
        const r = await checkSession();
        sendResponse({ ok: true, data: r });
        return;
      }

      if (msg.action === "MYDTU_SYNC_TIMETABLE") {
        const r = await syncTimetableFromTab();
        sendResponse(r);
        return;
      }

      sendResponse({ ok: false, error: `Unknown action: ${msg.action}` });
    } catch (e) {
      sendResponse({ ok: false, error: String(e?.message || e) });
    }
  })();

  return true;
});