"use client";

import React from "react";

type ExtResponse = {
  source: "mydtu-assistant-extension";
  requestId: string;
  ok: boolean;
  data?: any;
  error?: string;
};

const WEB_SOURCE = "mydtu-assistant-web";
const EXT_SOURCE = "mydtu-assistant-extension";

function sendToExtension(action: string, payload?: any): Promise<ExtResponse> {
  const requestId = `${Date.now()}_${Math.random().toString(16).slice(2)}`;

  return new Promise((resolve, reject) => {
    const timeout = window.setTimeout(() => {
      window.removeEventListener("message", onMessage);
      reject(new Error("Extension did not respond (timeout)."));
    }, 8000);

    function onMessage(event: MessageEvent) {
      const msg = event.data as ExtResponse;
      if (!msg || typeof msg !== "object") return;
      if (msg.source !== EXT_SOURCE) return;
      if (msg.requestId !== requestId) return;

      window.clearTimeout(timeout);
      window.removeEventListener("message", onMessage);
      resolve(msg);
    }

    window.addEventListener("message", onMessage);

    window.postMessage(
      {
        source: WEB_SOURCE,
        requestId,
        action,
        payload: payload ?? null
      },
      "*"
    );
  });
}

export default function ExtensionConnect() {
  const [status, setStatus] = React.useState<
    "idle" | "checking" | "connected" | "not_connected" | "error"
  >("idle");
  const [message, setMessage] = React.useState<string>("");

  async function handleOpenLogin() {
    setMessage("");
    try {
      const res = await sendToExtension("MYDTU_OPEN_LOGIN");
      if (!res.ok) throw new Error(res.error || "Open login failed");
      setMessage("Đã mở tab MYDTU. Hãy đăng nhập, rồi quay lại bấm “Kiểm tra kết nối”.");
    } catch (e: any) {
      setStatus("error");
      setMessage(e?.message || String(e));
    }
  }

  async function handleCheck() {
    setStatus("checking");
    setMessage("");
    try {
      const res = await sendToExtension("MYDTU_CHECK_SESSION");
      if (!res.ok) throw new Error(res.error || "Check session failed");

      const connected = !!res.data?.connected;
      if (connected) {
        setStatus("connected");
        setMessage("✅ Đã kết nối MYDTU (đã đăng nhập).");
      } else {
        setStatus("not_connected");
        setMessage("❌ Chưa đăng nhập MYDTU. Bấm “Kết nối MYDTU” để đăng nhập 1 lần.");
      }
    } catch (e: any) {
      setStatus("error");
      setMessage(e?.message || String(e));
    }
  }

  return (
    <div className="rounded-2xl border border-slate-800 bg-slate-950/40 p-4">
      <div className="flex flex-wrap items-center gap-3">
        <button
          onClick={handleOpenLogin}
          className="rounded-xl border border-slate-700 bg-slate-900 px-4 py-2 text-sm hover:bg-slate-800"
        >
          Kết nối MYDTU
        </button>

        <button
          onClick={handleCheck}
          className="rounded-xl border border-slate-700 bg-slate-900 px-4 py-2 text-sm hover:bg-slate-800"
        >
          Kiểm tra kết nối
        </button>

        <span className="text-sm text-slate-300">
          Trạng thái:{" "}
          {status === "idle"
            ? "Chưa kiểm tra"
            : status === "checking"
            ? "Đang kiểm tra..."
            : status === "connected"
            ? "Đã kết nối"
            : status === "not_connected"
            ? "Chưa kết nối"
            : "Lỗi"}
        </span>
      </div>

      {message ? <div className="mt-2 text-sm text-slate-200">{message}</div> : null}
    </div>
  );
}